import S from 'fluent-json-schema';

const refillSchema = {
  params: S.object().prop('prescriptionId', S.string().format(S.FORMATS.UUID)).required(),
  body: S.object()
    .prop('preferredPharmacyNpi', S.string().minLength(10).maxLength(10))
    .prop('deliveryAddress', S.string())
    .required(['preferredPharmacyNpi'])
};

fastify.post('/telehealth/prescriptions/:prescriptionId/refill', {
  schema: refillSchema,
  preHandler: [fastify.auth([fastify.verifyPatientToken])]
}, async (req, reply) => {
  const { prescriptionId } = req.params;
  const { preferredPharmacyNpi, deliveryAddress } = req.body;

  const result = await drizzleClient.update(prescriptionsTable)
    .set({
      refillStatus: 'PENDING_APPROVAL',
      pharmacyNpi: preferredPharmacyNpi,
      shippingAddress: deliveryAddress,
      requestedAt: new Date()
    })
    .where(and(
      eq(prescriptionsTable.id, prescriptionId),
      eq(prescriptionsTable.patientId, req.user.patientId)
    ))
    .returning();

  if (!result.length) {
    return reply.status(403).send({ error: 'Prescription not found or unauthorized' });
  }
  return reply.send(result[0]);
});
